import sys; sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/deps')
import zstandard as zstd, io
from classify_responses import complete_frames
def frame(winbyte, payload=b'hi'):
    out=bytearray((0xfd2fb528).to_bytes(4,'little')); out+=bytes([0x00, winbyte])
    out+=((0)|(0<<1)|(len(payload)<<3)|(1<<0)).to_bytes(3,'little'); out+=payload
    return bytes(out)
for w,name in [(136,'128MiB'),(137,'192MiB'),(144,'256MiB'),(0,'8KiB')]:
    b=frame(w)
    print(name, zstd.get_frame_parameters(b).window_size, end=' ')
    try: complete_frames(b); print('walk OK', end=' ')
    except Exception as e: print('walk REJECT(%s)'%e, end=' ')
    try:
      zstd.ZstdDecompressor(max_window_size=128*1024**2).stream_reader(io.BytesIO(b),read_across_frames=True).read(); print('lib OK')
    except Exception as e: print('lib REJECT', type(e).__name__)
"
